import re,os,json
from urllib.parse import urljoin
base='https://www.danvilleharvest.com/'
files=['home.html','menu.html','events.html','contact.html','reservations.html']
pagemap={'home.html':base,'menu.html':base+'menu','events.html':base+'events','contact.html':base+'contact','reservations.html':base+'reservations'}
found={}
for f in files:
    h=open(f,encoding='utf-8',errors='replace').read()
    urls=set()
    for m in re.findall(r'<img[^>]+>',h):
        for attr in ['src','data-src','data-image','content']:
            mm=re.search(attr+r'=\"([^\"]+)\"',m)
            if mm: urls.add(mm.group(1))
        ss=re.search(r'srcset=\"([^\"]+)\"',m)
        if ss:
            for part in ss.group(1).split(','):
                u=part.strip().split(' ')[0]
                if u: urls.add(u)
    for m in re.findall(r'(?:data-src|data-image|data-original)=\"([^\"]+)\"',h): urls.add(m)
    for m in re.findall(r'property=\"og:image\"[^>]*content=\"([^\"]+)\"',h): urls.add(m)
    for m in re.findall(r'content=\"([^\"]+)\"[^>]*property=\"og:image\"',h): urls.add(m)
    for m in re.findall(r'background-image\s*:\s*url\(([^)]+)\)',h): urls.add(m.strip('\'\" '))
    for m in re.findall(r'\"(https://images\.squarespace-cdn\.com/[^\"\\\\ ]+)\"',h): urls.add(m)
    for m in re.findall(r'\"(https://static1\.squarespace\.com/[^\"\\\\ ]+\.(?:jpg|jpeg|png|webp|gif))\"',h,re.I): urls.add(m)
    clean=set()
    for u in urls:
        if u.startswith('data:'): continue
        u=u.replace('&amp;','&')
        u=urljoin(pagemap[f],u)
        if not re.search(r'\.(jpg|jpeg|png|webp|gif|svg)(\?|\$|\b|$)',u,re.I) and 'squarespace-cdn' not in u: continue
        clean.add(u)
    found[pagemap[f]]=sorted(clean)
    print('===',f,len(clean))
    for u in sorted(clean): print('   ',u)
json.dump(found,open('raw_images.json','w'),indent=1)
"

